package com.expensetracker.controller;
import com.expensetracker.dto.*;import com.expensetracker.service.CategoryService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/categories") public class CategoryController {private final CategoryService s;public CategoryController(CategoryService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public CategoryResponseDTO create(@Valid @RequestBody CategoryRequestDTO r){return s.create(r);}@GetMapping public List<CategoryResponseDTO> all(@RequestParam Long userId){return s.all(userId);}@PutMapping("/{id}") public CategoryResponseDTO update(@PathVariable Long id,@Valid @RequestBody CategoryRequestDTO r){return s.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@RequestParam Long userId){s.delete(id,userId);}}
